/**
 * The legacy site's URLs, for the merged /sitemap.xml.
 *
 * The legacy blog, docs and legal pages are generated by `scripts/build-blog.js` at the repo root, and
 * that script writes its own `sitemap.xml` (every post with its real `lastmod`). nginx serves those
 * pages; Next serves `/sitemap.xml`. So the container build copies the generated file next to this app
 * as `legacy-sitemap.xml` (see the Dockerfile) and `src/app/sitemap.ts` folds it in at build time.
 * Outside Docker, `../sitemap.xml` (the file committed at the repo root) is the fallback.
 *
 * Only canonical, live sections are kept: `/blog`, `/blog/<slug>`, `/docs`, `/docs/**`, `/privacy`
 * and `/terms`. Everything else in the legacy file is dropped on purpose: `/` (the revamp owns it)
 * and `/about`, `/editorial`, `/authors` and the author pages, which return 404 in production.
 * Server-only (reads the filesystem at build time).
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { SITE_URL } from "@/lib/links";

export interface LegacyUrl {
  /** Site path, for example "/blog/some-post". */
  path: string;
  /** W3C date (YYYY-MM-DD) from the legacy file, when present. */
  lastModified?: string;
}

// Build-time reads of two known files outside `src/`; the ignore comments keep Turbopack from tracing the whole project.
const CANDIDATES = [
  path.join(/*turbopackIgnore: true*/ process.cwd(), "legacy-sitemap.xml"),
  path.join(/*turbopackIgnore: true*/ process.cwd(), "..", "sitemap.xml"),
];

const KEEP = [/^\/blog$/, /^\/blog\/[a-z0-9-]+$/, /^\/docs$/, /^\/docs\/[a-z0-9/-]+$/, /^\/privacy$/, /^\/terms$/];

const DATE = /^\d{4}-\d{2}-\d{2}/;

export function readLegacyUrls(): LegacyUrl[] {
  const file = CANDIDATES.find((candidate) => existsSync(candidate));
  if (!file) return [];
  const xml = readFileSync(file, "utf8");
  const seen = new Set<string>();
  const urls: LegacyUrl[] = [];
  for (const block of xml.match(/<url>[\s\S]*?<\/url>/g) ?? []) {
    const loc = block.match(/<loc>\s*([^<\s]+)\s*<\/loc>/)?.[1];
    if (!loc || !loc.startsWith(`${SITE_URL}/`)) continue;
    const pathname = loc.slice(SITE_URL.length).replace(/\/+$/, "");
    if (seen.has(pathname) || !KEEP.some((rule) => rule.test(pathname))) continue;
    seen.add(pathname);
    const lastmod = block.match(/<lastmod>\s*([^<\s]+)\s*<\/lastmod>/)?.[1];
    urls.push({ path: pathname, ...(lastmod && DATE.test(lastmod) ? { lastModified: lastmod.slice(0, 10) } : {}) });
  }
  return urls;
}
